mapper.select:
SELECT sbr.id, sbr.code, sbr.platform_return_no as platformReturnNo, sbr.platform_order_no as platformOrderNo, sbr.so_id as soId, sbr.so_code as soCode, sbr.dict_platform as platform, sbr.shop_id as shopId, sbr.amount as orderAmount, sbr.currency, sbr.type, sbr.reason, sbr.status, sbr.platform_status as platformStatus, sbrd.id as detailId, sbrd.sku_id as skuId, sbrd.sku_no as skuNo, sbrd.platform_sku_no as platformSkuNo, sbrd.sale_qty as saleQty, sbrd.return_qty as returnQty, sbrd.remark, sbr.create_time as sysCreateTime, sbr.sys_return_time as sysReturnTime, sbr.return_logistic_code as returnLogisticCode, sbr.update_time as updateTime, sbr.approve_user_id as approveUserId, sbr.approve_user_name as approveUserName, sbr.approve_time as approveTime, sbr.create_user_name as createUserName from so_b2c_return sbr inner join so_b2c_return_detail sbrd on sbr.id = sbrd.main_id and sbrd.is_deleted = false where ${params.sqlMap.default} and sbr.is_deleted =FALSE
${params.permissionSql}
order by sbr.create_time desc

SELECT sbr.id, sbr.code, sbr.so_id as soId, sbr.status, sbr.return_logistic_code as returnLogisticCode, sbr.dict_platform as platform, sbr.shop_id as shopId, sbrd.id as detailId, sbrd.sku_id as skuId, sbrd.sku_no as skuNo, sbrd.sale_qty as saleQty, sbrd.return_qty as returnQty from so_b2c_return sbr inner join so_b2c_return_detail sbrd on sbr.id = sbrd.main_id and sbrd.is_deleted = false where sbr.id in
#{id}
and sbr.is_deleted =FALSE order by sbr.create_time

SELECT sr.so_id AS sourceId, -- sr.customer_id, sd.warehouse_id, sr.currency, -- sr.currency_Symbol, si.ID AS soId, sd.warehouse_org_id AS inventoryOrgId, CASE WHEN sd.qty > 0 THEN sd.qty ELSE 0 END AS salesQty, CASE WHEN sd.amount > 0 THEN sd.amount ELSE 0 END AS salesAmount, sd.is_gift, -- sd.is_close, srd.ID, srd.main_id, srd.sku_id, srd.sku_no, srd.remark, sr.type as returnTypeDict, sr.reason as returnReasonDict, srd.platform_sku_no FROM so_b2c_return sr INNER JOIN so_b2c_return_detail srd ON srd.main_id = sr.ID AND srd.is_deleted =FALSE LEFT JOIN so_b2c si ON sr.so_id = si.ID AND si.is_deleted = FALSE LEFT JOIN so_b2c_detail sd ON srd.so_detail_id = sd.ID AND sd.is_deleted = FALSE WHERE sr.is_deleted =FALSE
AND sr.id = #{dto.id}
AND srd.sku_no IN
#{skuNo}
AND srd.sku_no ILIKE concat('%',#{dto.remoteSearchSku}::text,'%')

SELECT sbr.id, sbrd.id AS detailId, sbr.code AS afterSaleCode, sbr.platform_return_no AS platformReturnNo, sbr.platform_order_no AS platformOrderNo, sbr.so_code AS soCode, sbr.dict_platform AS platform, sbr.shop_id AS shopId, sbr.type AS returnType, sbr.reason AS returnReason, sbrd.sku_id AS skuId, sbrd.sku_no AS skuNo, sbrd.return_qty AS returnQty, sbd.warehouse_name AS warehouseName FROM so_b2c_return_detail sbrd INNER JOIN so_b2c_return sbr ON sbrd.main_id = sbr.id AND sbrd.is_deleted = FALSE LEFT JOIN so_b2c_detail sbd ON sbrd.so_detail_id = sbd.id AND sbd.is_deleted = FALSE WHERE ${params.sqlMap.default} AND sbr.is_deleted = FALSE
AND sbrd.sku_no IN
#{skuNo}
ORDER BY
${item.field} ${item.sort}
sbr.create_time DESC
